from __future__ import annotations

import pytest

from llm_router import LLMRouter, Model, Provider, RouterProfile
from tests.llm_router.support.fault_server import ScriptedHTTPServer
from tests.llm_router.support.workers.worker_patches import patched_openai_sdk

pytestmark = pytest.mark.verification_kind("unit")


def _router() -> LLMRouter:
    return LLMRouter(
        RouterProfile(model=Model.DEEPSEEK_V3, provider=Provider.OPENROUTER),
        temperature=0.0,
    )


@pytest.mark.verifies("REQ_MULTIMODAL_CONTENT_NORMALIZATION[revision==2]")
@pytest.mark.parametrize(
    "value",
    [
        pytest.param(b"", id="empty-bytes"),
        pytest.param(bytearray(b""), id="empty-bytearray"),
        pytest.param(b"payload", id="nonempty-bytes"),
    ],
)
def test_bytes_like_content_is_rejected_locally(
    monkeypatch: pytest.MonkeyPatch, value: bytes | bytearray
) -> None:
    monkeypatch.setenv("OPENROUTER_API_KEY_1", "assurance-openai-key")

    with (
        ScriptedHTTPServer(port=0, routes={}) as server,
        patched_openai_sdk(
            forced_base_url=f"{server.base_url}/v1",
            disable_sdk_retries=True,
        ),
        pytest.raises(TypeError, match=r"Unsupported media value: byte(s|array)\."),
    ):
        _router().query(value)  # type: ignore[arg-type]
